export function defaults() { return { light_response: 0, light_emission: 0, bright_radius: 2, dim_radius: 4, angle: 360, animation: 'none', x: 0, y: 0, kind: 'smoke', scale: 3, density: .6, color: '#9aa3ad', enabled: true, rotation: 0, name: 'Shader', source: 'void main() { float a = 0.35 * uIntensity; finalColor = vec4(uColor * a, a); }', radius: 0, opacity: 1, intensity: .6, speed: 1, blend_mode: 'normal' }; }
export function effects(state, layer = 'effects') { if (layer === 'lighting')
    return state.lights.map(data => ({ ...data, kind: 'light', key: `light:${data.id}`, data: { ...defaults(), ...data, enabled: Boolean(data.enabled) } })); return [...state.particles.map(data => ({ ...data, kind: 'particle', data: { ...defaults(), ...data, enabled: Boolean(data.enabled) } })), ...state.shaders.map(data => ({ ...data, kind: 'shader', data: { ...defaults(), ...data, enabled: Boolean(data.enabled) } }))].map(e => ({ ...e, key: `${e.kind}:${e.id}` })); }
export function hitEffect(items, point, scale) { return [...items].reverse().find(e => Math.hypot(e.x - point.x, e.y - point.y) <= 13 / scale); }
export function inMarquee(items, from, to) { return items.filter(e => e.x >= Math.min(from.x, to.x) && e.x <= Math.max(from.x, to.x) && e.y >= Math.min(from.y, to.y) && e.y <= Math.max(from.y, to.y)).map(e => e.key); }
export function payload(kind, data) { const keys = kind === 'light' ? 'x y bright_radius dim_radius angle rotation animation intensity color enabled' : kind === 'particle' ? 'x y kind scale density color enabled rotation light_response light_emission' : 'name source x y radius scale intensity opacity speed color rotation blend_mode enabled light_response light_emission'; return Object.fromEntries(keys.split(' ').map(key => [key, data[key]])); }
export function translatedCopies(items, at) { const center = { x: items.reduce((n, e) => n + e.x, 0) / items.length, y: items.reduce((n, e) => n + e.y, 0) / items.length }; return items.map(e => ({ kind: e.kind, data: payload(e.kind, { ...e.data, x: at.x + e.x - center.x, y: at.y + e.y - center.y }) })); }
